#include <unordered_map>
#include <queue>
#include <vector>
using namespace std;
vector<int> topKFrequent(vector<int>&nums, int k) {
    unordered_map<int, int>f;
    for (int x:nums)f[x]++;
    auto cmp=[&](int a, int b) {
        return f[a]>f[b];
    };
    priority_queue<int, vector<int>, decltype(cmp)>h(cmp);
    for (auto&[v, _]:f) {
        h.push(v);
        if ((int)h.size()>k)h.pop();
    }
    vector<int>r;
    while (!h.empty()) {
        r.push_back(h.top());
        h.pop();
    }
    return r;
}

